fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2 with no divisors other than 1 and itself.
    // For all n < 2, return false immediately.
    if n < 2 {
        return false;
    }

    // We will check all candidate divisors k starting from 2 up to n-1.
    // Loop invariants:
    // - n >= 2 (established by the initial check)
    // - candidate divisor k is in [2, n]
    // - for all j in [2, k), n % j != 0 (i.e., checked no divisors so far)
    //
    // Termination measure: n - k, strictly decreases each iteration.

    let mut k = 2;
    while k < n {
        if n % k == 0 {
            // Found a divisor != 1 and n, so n is not prime.
            return false;
        }
        k += 1;
    }

    // No divisors found, per the definition n is prime.
    true
}